scripts:
Chart.defaults.font.family = "'Segoe UI','Helvetica Neue',Arial,sans-serif";
Chart.defaults.color = '#5b6472';

new Chart(document.getElementById('segChart'), {
  type: 'doughnut',
  data: {
    labels: ['Productividad y procesos', 'Nube inteligente', 'Cómputo personal'],
    datasets: [{
      data: [120810, 106265, 54649],
      backgroundColor: ['#1a56db', '#5b8def', '#d97706'],
      borderWidth: 2, borderColor: '#fff'
    }]
  },
  options: { plugins:{legend:{position:'bottom', labels:{font:{size:11}}}} }
});

new Chart(document.getElementById('geoChart'), {
  type: 'doughnut',
  data: {
    labels: ['EE. UU.', 'Fuera de EE. UU.'],
    datasets: [{ data: [144546, 137178], backgroundColor: ['#111318', '#c9d3ff'], borderWidth:2, borderColor:'#fff' }]
  },
  options: { plugins:{legend:{position:'bottom', labels:{font:{size:11}}}} }
});

new Chart(document.getElementById('cloudChart'), {
  type: 'bar',
  data: {
    labels: ['FY2023','FY2024','FY2025','FY2026(prov.)'],
    datasets: [{ label:'Ingresos de Microsoft Cloud ($M)', data:[111600,137400,168900,214000], backgroundColor:'#1a56db', borderRadius:5 }]
  },
  options: { plugins:{legend:{display:false}}, scales:{y:{beginAtZero:true}} }
});

new Chart(document.getElementById('finChart'), {
  type: 'line',
  data: {
    labels: ['FY2021','FY2022','FY2023','FY2024','FY2025'],
    datasets: [
      { label:'Ingresos', data:[168100,198300,211900,245100,281700], borderColor:'#1a56db', backgroundColor:'#1a56db', tension:.25 },
      { label:'Utilidad operativa', data:[69900,83400,88500,109400,128500], borderColor:'#0a7d3c', backgroundColor:'#0a7d3c', tension:.25 },
      { label:'FCF', data:[56100,65100,59500,74100,71600], borderColor:'#d97706', backgroundColor:'#d97706', tension:.25 }
    ]
  },
  options: { plugins:{legend:{position:'bottom', labels:{font:{size:11}}}, title:{display:true, text:'Ingresos, utilidad operativa y FCF ($M)', font:{size:12}}} }
});

new Chart(document.getElementById('debtChart'), {
  type: 'bar',
  data: {
    labels: ['FY2022','FY2023','FY2024','FY2025'],
    datasets: [{ label:'Deuda total ($M)', data:[49800,47200,51600,43200], backgroundColor:'#c22', borderRadius:5 }]
  },
  options: { plugins:{legend:{display:false}, title:{display:true, text:'Deuda total (corto plazo + porción corriente de largo plazo + largo plazo)', font:{size:12}}}, scales:{y:{beginAtZero:true}} }
});
